#include <string>
#include <iostream>

// Define a user-defined literal for a custom string type
std::string operator"" s(const char* str, size_t len) {
    return std::string(str, len);
}

int main() {
    auto myString = "Hello"s; // invokes the user-defined literal operator"" s
    std::cout << myString << std::endl;
    return 0;
}
